using Mapster;

public static class CustomerMappings
{
    // Compiles and runs. After the rename, Email is null, and Status is
    // copied by number, so Suspended becomes Active.
    public static CustomerDto ToDto(Customer customer) =>
        customer.Adapt<CustomerDto>();

    // Copies every member whose name matches, Name = null included
    public static void Apply(UpdateCustomer request, Customer customer) =>
        request.Adapt(customer);
}

using Mapster;

public static class MappingConfig
{
    // Call once at startup, and again from a unit test
    public static void Register(TypeAdapterConfig config)
    {
        config.RequireExplicitMapping = true;         // no unregistered pairs
        config.RequireDestinationMemberSource = true; // no unmapped members
        config.Default.EnumMappingStrategy(EnumMappingStrategy.ByName);

        config.NewConfig<Customer, CustomerDto>()
            .Map(dest => dest.Email, src => src.EmailAddress);

        // Throws a CompileException naming any unmapped member
        config.Compile();
    }
}

