public sealed class CustomerSummary
{
    public required int Id { get; init; }
    public required string Email { get; init; }
}

public static class CustomerMapper
{
    // A new required member breaks this method at compile time (CS9035)
    public static CustomerSummary ToSummary(Customer c) =>
        new() { Id = c.Id, Email = c.EmailAddress };

    // Writes name the fields a request may change, nothing else
    public static void Apply(UpdateCustomer request, Customer customer) =>
        customer.Name = request.Name ?? customer.Name;
}
